import java.util.HashMap;
import java.util.Map;

Map returnMap = new HashMap();
String raw = account.getStringAttribute("EMPLOYEE_ID");
if (raw != null) {
  String normalized = raw.replaceFirst("^0+(?!$)", "");
  returnMap.put("identityAttributeName", "employeeNumber");
  returnMap.put("identityAttributeValue", normalized);
}
return returnMap;
